+  }
+  const parent = path.dirname(lexicalFile);
+  if (!fs.existsSync(parent)) throw new Error('pre-created output parent is required');
+  const relativeParent = path.relative(lexicalRoot, parent);
+  let cursor = lexicalRoot;
+  for (const segment of relativeParent.split(path.sep).filter(Boolean)) {
+    cursor = path.join(cursor, segment);
+    if (fs.lstatSync(cursor).isSymbolicLink()) throw new Error('symlink output component is forbidden');
+  }
+  const resolvedParent = fs.realpathSync(parent);
+  if (resolvedParent !== root && !resolvedParent.startsWith(`${root}${path.sep}`)) throw new Error('output parent escaped approved maker root');
+  const parentStat = fs.statSync(resolvedParent);
+  if (parentStat.uid !== uid || parentStat.gid !== gid || (parentStat.mode & 0o077) !== 0) {
+    throw new Error('generation output parent ownership or mode mismatch');
+  }
+  if (fs.existsSync(lexicalFile) || fs.lstatSync(parent).isSymbolicLink()) throw new Error('immutable output already exists or has symlink parent');
+  return lexicalFile;
+}
+
+export function writeImmutableJson(file, value) {
+  const bytes = Buffer.from(`${JSON.stringify(value, null, 2)}\n`);
+  const flags = fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL
+    | (fs.constants.O_NOFOLLOW ?? 0);
+  const descriptor = fs.openSync(file, flags, 0o640);
+  try {
+    fs.writeFileSync(descriptor, bytes);
+    fs.fsyncSync(descriptor);
+  } finally {
+    fs.closeSync(descriptor);
+  }
+  const directory = fs.openSync(path.dirname(file), fs.constants.O_RDONLY);
+  try {
+    fs.fsyncSync(directory);
+  } finally {
+    fs.closeSync(directory);
+  }
+  const readback = fs.readFileSync(file);
+  const stat = fs.statSync(file);
+  if (!readback.equals(bytes) || (stat.mode & 0o777) !== 0o640) throw new Error('immutable output readback mismatch');
+  return {
+    sha256: sha256Bytes(readback), byte_length: readback.length, media_type: 'application/json',
+    uid: stat.uid, gid: stat.gid, mode: (stat.mode & 0o777).toString(8).padStart(4, '0'),
+  };
+}
+
+export function prepareImmutableJson(file, value) {
+  const bytes = Buffer.from(`${JSON.stringify(value, null, 2)}\n`);
+  const temporary = path.join(path.dirname(file), `.${path.basename(file)}.prepare.${crypto.randomBytes(12).toString('hex')}`);
+  const descriptor = fs.openSync(temporary, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL
+    | (fs.constants.O_NOFOLLOW ?? 0), 0o640);
+  try {
+    fs.writeFileSync(descriptor, bytes);
+    fs.fsyncSync(descriptor);
+  } finally {
+    fs.closeSync(descriptor);
+  }
+  return { file, temporary, bytes };
+}
+
+export function commitPreparedJson(prepared) {
+  if (fs.existsSync(prepared.file)) throw new Error('immutable output already exists');
+  fs.linkSync(prepared.temporary, prepared.file);
+  fs.unlinkSync(prepared.temporary);
+  const directory = fs.openSync(path.dirname(prepared.file), fs.constants.O_RDONLY);
+  try { fs.fsyncSync(directory); } finally { fs.closeSync(directory); }
+  const readback = fs.readFileSync(prepared.file);
+  const stat = fs.statSync(prepared.file);
+  if (!readback.equals(prepared.bytes) || (stat.mode & 0o777) !== 0o640) throw new Error('prepared output readback mismatch');
+  return { sha256: sha256Bytes(readback), byte_length: readback.length, media_type: 'application/json',
+    uid: stat.uid, gid: stat.gid, mode: (stat.mode & 0o777).toString(8).padStart(4, '0') };
+}
+
+export function abortPreparedJson(prepared) {
+  if (prepared?.temporary && fs.existsSync(prepared.temporary)) fs.unlinkSync(prepared.temporary);
+}
+
+export function writeCheckpointJson(file, value, approvedRoot, principal) {
+  const lexicalRoot = path.resolve(approvedRoot);
+  const lexicalFile = path.resolve(file);
+  if (!path.isAbsolute(file) || lexicalFile === lexicalRoot || !lexicalFile.startsWith(`${lexicalRoot}${path.sep}`)) {
+    throw new Error('checkpoint path escaped approved maker root');
+  }
+  if (fs.lstatSync(lexicalRoot).isSymbolicLink()) throw new Error('symlink checkpoint root is forbidden');
+  const rootStat = fs.statSync(lexicalRoot);
+  if (!rootStat.isDirectory() || rootStat.uid !== principal.uid || rootStat.gid !== principal.gid || (rootStat.mode & 0o077) !== 0) {
+    throw new Error('maker checkpoint root ownership or mode mismatch');
+  }
+  const parent = path.dirname(lexicalFile);
+  const relativeParent = path.relative(lexicalRoot, parent);
+  let cursor = lexicalRoot;
+  for (const segment of relativeParent.split(path.sep).filter(Boolean)) {
+    cursor = path.join(cursor, segment);
+    if (fs.lstatSync(cursor).isSymbolicLink()) throw new Error('symlink checkpoint component is forbidden');
+  }
+  if (fs.existsSync(lexicalFile)) {
+    const current = fs.lstatSync(lexicalFile);
+    if (!current.isFile() || current.isSymbolicLink() || current.uid !== principal.uid || current.gid !== principal.gid
+        || (current.mode & 0o777) !== 0o600) throw new Error('existing checkpoint ownership or mode mismatch');
+  }
+  const bytes = Buffer.from(`${JSON.stringify(value, null, 2)}\n`);
+  const temporary = path.join(parent, `.${path.basename(file)}.${process.pid}.${crypto.randomBytes(8).toString('hex')}`);
+  const flags = fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL
+    | (fs.constants.O_NOFOLLOW ?? 0);
+  const descriptor = fs.openSync(temporary, flags, 0o600);
+  try {
+    fs.writeFileSync(descriptor, bytes);
+    fs.fsyncSync(descriptor);
+  } finally {
+    fs.closeSync(descriptor);
+  }
+  try {
+    fs.renameSync(temporary, lexicalFile);
+    const directory = fs.openSync(parent, fs.constants.O_RDONLY);
+    try {
+      fs.fsyncSync(directory);
+    } finally {
+      fs.closeSync(directory);
+    }
+  } finally {
+    if (fs.existsSync(temporary)) fs.unlinkSync(temporary);
+  }
+  const readback = fs.readFileSync(lexicalFile);
+  if (!readback.equals(bytes)) throw new Error('checkpoint readback mismatch');
+  return { sha256: sha256Bytes(readback), byte_length: readback.length };
+}
+
+export function boundedQuestionRows(pages, question) {
+  const firstPage = question.page_chain[0];
+  const firstRows = pages.get(firstPage);
+  if (!firstRows) throw new Error('missing first page in extracted page chain');
+  const start = firstRows.findIndex((row) => row.minX < 65
+    && new RegExp(`^\\s*${question.question_label}(?:\\s+\\S|\\s*$)`).test(row.text));
+  if (start < 0) throw new Error('printed question boundary start was not found');
+
+  const bounded = [];
+  let reachedFollowingQuestion = false;
+  for (const pageNumber of question.page_chain) {
+    const rows = pages.get(pageNumber);
+    if (!rows) throw new Error('missing continuation page in extracted page chain');
+    let selected = pageNumber === firstPage ? rows.slice(start) : [...rows];
+    const following = question.following_question_label;
+    if (following) {
+      const boundary = selected.findIndex((row) => row.minX < 65
+        && new RegExp(`^\\s*${following}(?:\\s+\\S|\\s*$)`).test(row.text));
+      if (boundary >= 0) {
+        if (question.following_question_page && pageNumber !== question.following_question_page) {
+          throw new Error('printed question boundary page mismatch');
+        }
+        selected = selected.slice(0, boundary);
+        reachedFollowingQuestion = true;
+      }
+      else if (pageNumber === question.following_question_page) throw new Error('printed question boundary end was not found');
+    }
+    bounded.push(...selected.map((row) => ({ ...row, page_number: pageNumber })));
+    if (reachedFollowingQuestion) break;
+  }
+  if (bounded.length === 0 || !bounded.some((row) => row.text.trim())) throw new Error('bounded question transcription is empty');
+  return bounded;
+}
