+export function visualDisposition({ questionText, pageEvidence }) {
+  const textualCue = /\b(diagram|figure|graph|curve|sketch|table|shaded|region|grid|axes|axis|histogram|tree)\b/i.test(questionText);
+  const imageOperators = pageEvidence.reduce((sum, item) => sum + item.image_operator_count, 0);
+  const vectorOperators = pageEvidence.reduce((sum, item) => sum + item.vector_path_operator_count, 0);
+  const rendered = pageEvidence.length > 0 && pageEvidence.every((item) => /^[0-9a-f]{64}$/.test(item.render_sha256));
+  return {
+    presence: textualCue ? 'present' : (imageOperators > 0 || vectorOperators > 0 ? 'undetermined' : 'absent'),
+    completeness: rendered ? 'complete_page_chain_rendered' : 'incomplete',
+    method: 'source_text_cue_plus_pdf_operator_and_page_render_evidence',
+    signal_scope: 'complete_source_pages; operator signals are not question-region claims',
+    signals: { textual_cue: textualCue, image_operator_count: imageOperators, vector_path_operator_count: vectorOperators },
+  };
+}
